fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let ax: i32 = w / 3;
    let ay: i32 = h / 2;
    let bx: i32 = w * 2 / 3;
    let by: i32 = h / 2;
    let cell: i32 = 8;
    let mut y: i32 = 0;
    while y < h {
        let mut x: i32 = 0;
        while x < w {
            let mx: i32 = x + cell / 2;
            let my: i32 = y + cell / 2;
            let d1: i32 = (mx - ax) * (mx - ax) + (my - ay) * (my - ay);
            let d2: i32 = (mx - bx) * (mx - bx) + (my - by) * (my - by);
            let v: i32 = tab[((d1 >> 8) - t) & 31] + tab[((d2 >> 8) - t) & 31];
            let b: i32 = (v + 254) * 255 / 508;
            let c: i32 = (b / 4) * 65536 + (b * 2 / 3) * 256 + b;
            host::display::fill_rect(x, y, cell, cell, c);
            x = x + cell;
        }
        y = y + cell;
    }
    host::display::present();
}
